DO $$ BEGIN IF NOT EXISTS ( SELECT 1 FROM information_schema.columns WHERE table_name = 'scores' AND column_name = 'assessment' ) THEN ALTER TABLE scores ADD COLUMN assessment text NOT NULL DEFAULT 'Assessment 1'; END IF; END $$; DO $$ BEGIN IF NOT EXISTS ( SELECT 1 FROM pg_constraint WHERE conname = 'scores_student_subject_term_assessment_unique' ) THEN ALTER TABLE scores ADD CONSTRAINT scores_student_subject_term_assessment_unique UNIQUE (student_id, subject_id, term, assessment); END IF; END $$;